<?php get_header(); ?><section class="or-category-hero"><div class="or-container"><?php or_breadcrumbs(); ?><p class="or-eyebrow">Conteúdo editorial</p><h1><?php echo esc_html(post_type_archive_title('',false)); ?></h1><p>Artigos, guias e análises organizados para ajudar você a pesquisar antes de comprar.</p></div></section><section class="or-section"><div class="or-container"><div class="or-grid-3"><?php if(have_posts()): while(have_posts()): the_post(); ?><article class="or-card"><?php if(has_post_thumbnail()) the_post_thumbnail('large',array('class'=>'or-card-image','loading'=>'lazy')); ?><div class="or-card-body"><p class="or-eyebrow">Artigo</p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),22)); ?></p><a class="or-card-link" href="<?php the_permalink(); ?>">Leia mais →</a></div></article><?php endwhile; else: ?><p>Nenhum artigo publicado ainda.</p><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php get_footer(); ?>
